import json, subprocess, sys, hashlib, os

def hexify(s):
    if isinstance(s, str): s = s.encode()
    return s.hex()

def req(method, uri, headers, body=b""):
    """headers: list of (name, value) raw lines"""
    lines = [method + " " + uri + " SIP/2.0"]
    for n, v in headers:
        lines.append(n + ": " + v)
    return ("\r\n".join(lines) + "\r\n\r\n").encode() + body

def basic_req(**kw):
    method = kw.get("method", "MESSAGE")
    uri = kw.get("uri", "sip:bob@lab.test")
    frm = kw.get("frm", "sip:alice@lab.test;tag=t1")
    to = kw.get("to", "<sip:bob@lab.test>")
    cid = kw.get("cid", "c1")
    cseq = kw.get("cseq", "1")
    extra = kw.get("extra", [])
    body = kw.get("body", b"")
    hs = [("From", frm), ("To", to), ("Call-ID", cid), ("CSeq", cseq + " " + method)] + extra
    hs.append(("Content-Length", str(len(body))))
    return req(method, uri, hs, body)

def cfg(accounts=None, peers=None, ttl=1000, capacity=10):
    if accounts is None:
        accounts = [{"id": "alice", "default": "sip:alice@lab.test",
                     "aliases": ["sip:alice@lab.test", "sip:desk@lab.test", "tel:+12025550100"]},
                    {"id": "bob", "default": "sip:bob@lab.test",
                     "aliases": ["sip:bob@lab.test"]}]
    if peers is None:
        peers = [{"id": "edge", "mode": "access", "accounts": []},
                 {"id": "relay", "mode": "relay", "accounts": ["alice", "bob"]}]
    return {"accounts": accounts, "peers": peers, "ttl_ms": ttl, "capacity": capacity}

def env(config, events):
    return {"version": 1, "config": config, "events": events}

def ev(t, peer, auth, egress, wire):
    return {"t": t, "peer": peer, "auth": auth, "egress": egress, "wire_hex": hexify(wire)}

def run(doc):
    p = subprocess.run([sys.executable, "-I", "-B", "/app/submission/main.py"],
                       input=json.dumps(doc).encode(), capture_output=True, timeout=60)
    return p

FAILS = []
def check(name, doc, expect, code=0):
    """expect: list of per-event expectations. Each is either a reason string (reject)
    or a dict of expected fields in the accept/replay result."""
    p = run(doc)
    if p.returncode != code:
        FAILS.append((name, "returncode %d != %d; stderr=%r" % (p.returncode, code, p.stderr[:400])))
        print("FAIL", name, p.returncode, p.stderr[:400])
        return None
    if code != 0:
        if p.stdout:
            FAILS.append((name, "stdout on error"))
            print("FAIL", name, "stdout not empty")
        print("ok", name)
        return None
    out = json.loads(p.stdout)
    res = out["results"]
    if len(res) != len(expect):
        FAILS.append((name, "len mismatch"))
        print("FAIL", name, json.dumps(out)[:1500])
        return out
    for i, (got, want) in enumerate(zip(res, expect)):
        if isinstance(want, str):
            if got.get("decision") != "reject" or got.get("reason") != want or set(got) != {"index","decision","reason"} or got["index"] != i:
                FAILS.append((name, "event %d: got %s want reject %s" % (i, got, want)))
                print("FAIL", name, "event", i, "got", got, "want", want)
        else:
            if got.get("decision") not in ("accept", "replay"):
                FAILS.append((name, "event %d: got reject %s want %s" % (i, got, want)))
                print("FAIL", name, "event", i, "got", got, "want", want)
                continue
            for k, v in want.items():
                if got.get(k) != v:
                    FAILS.append((name, "event %d field %s: got %r want %r" % (i, k, got.get(k), v)))
                    print("FAIL", name, "event", i, k, "got", got.get(k), "want", v)
            extra = set(got) - set(want) - {"index", "decision", "first"}
            if extra:
                FAILS.append((name, "event %d extra keys %s" % (i, extra)))
                print("FAIL", name, "event", i, "extra", extra)
    print("ok", name)
    return out

def check_env(name, doc):
    return check(name, doc, [], code=2)

def summary():
    print()
    if FAILS:
        print("FAILURES:", len(FAILS))
        for f in FAILS: print("  ", f)
    else:
        print("ALL PASS")
    return 1 if FAILS else 0
